    place.secondaryButton = CPTextButton(title: "Call", textStyle: .normal, handler: { (button) in
        MemoryLogger.shared.appendEvent("Calling \(phoneNumber).")
        self.carplayScene?.open(url, options: nil, completionHandler: nil)
    })
}
